    {t="C", q=8332, n="Dukes of the Council", pn="Duques do Conselho", lvl=60, req=60, xp=6600, cc=3, m=1451, x=20.46, y=86.16, ot="i", ahead={{q=8361, n="Abyssal Contacts", pn="Contatos abissais", i="Abyssal Crest", ip="Escudo Abissal", c=1}}, obj="Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.", pobj="Leve 1 Estilhaço Brilhante Grande e 3 Escudos Abissais para Aurel Folháurea no Forte Cenariano."},
    {t="C", q=8361, n="Abyssal Contacts", pn="Contatos abissais", lvl=60, req=60, xp=6600, cc=1, m=1451, x=20.46, y=86.16, ot="i", ahead={{q=8332, n="Dukes of the Council", pn="Duques do Conselho", i="Abyssal Crest", ip="Escudo Abissal", c=1}}, obj="Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.", pobj="Bor Juba Agreste no Forte Cenariano, em Silithus, quer que você acabe com um Templário Abissal e leve um Escudo Abissal para ele como prova."},
    {t="C", q=7786, n="Thunderaan the Windseeker", pn="Trovejardus, o Perseguidor dos Ventos", lvl=60, req=60, xp=9950, cc=10, ot="i", obj="To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.", pobj="Para libertar Trovejardus, o Perseguidor dos Ventos, de sua prisão, você deve entregar as metades direita e esquerda dos Grilhões do Perseguidor dos Ventos, 10 Barras de Elemêntio Encantadas e a Essência do Senhor do Fogo para o Grão-lorde Dimitriano em Silithus.", f={"coleta","drop"}},
