    {t="C", q=8306, n="Into The Maw of Madness", pn="No ventre da loucura", lvl=60, req=58, xp=9950, m=1414, x=44.4, y=86.11, ot="k", obj="Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And <Name>, remember the Commander's words: \"Do what you must...\"", pobj="O Comandante Mar'alith do Forte Cenariano em Silithus quer que você encontre Natália. A informação que conseguiu aponta para Colme'Régia, ao sul, como sendo a área em que você encontrará a Senhora Natália Mar'alith.  Não se esqueça de falar com os anões no acampamento do Barbabronze antes de se aventurar na colmeia. Eles podem ter algum trabalho e conselhos para você.  E, <name>, lembre-se das palavras do Comandante: \"Faça o que for necessário...\"", f={"elite","long"}},
    {t="C", q=8310, n="Breaking the Code", pn="Quebrando o código", lvl=60, req=58, xp=8300, cc=3, m=1451, x=23.43, y=59.56, ot="i", ahead={{q=1126, n="Hive in the Tower", pn="A colmeia da torre", i="Encrusted Silithid Object", ip="Objeto Silitídeo Incrustado", c=1, qi=true},{q=8301, n="The Path of the Righteous", pn="O caminho do íntegros", i="Silithid Carapace Fragment", ip="Fragmento de Carapaça Silitídea", c=1, qi=true}}, objs={{n="Hive'Ashi Silithid Brain", p="Cérebro de Silitídeo de Colme'Ashi", m=1451, x=45.72, y=26.85},{n="Hive'Zora Silithid Brain", p="Cérebro de Silitídeo de Colme'Zora", m=1451, x=23.43, y=59.56},{n="Hive'Regal Silithid Brain", p="Cérebro de Silitídeo de Colme'Régia", m=1451, x=62, y=80.34}}, obj="Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.", pobj="Frankal Pontepedra, no Acampamento Barbabronze, em Silithus, quer que você obtenha um Cérebro de Silitídeo de Colme'Zora, um Cérebro de Silitídeo de Colme'Ashi e um Cérebro de Silitídeo de Colme'Régia. Fale novamente com Frankal quando tiver concluído a tarefa."},
    {t="C", q=8348, n="Signet of the Dukes", pn="O sinete dos duques", lvl=60, req=60, xp=8300, cc=1, m=1451, x=37.63, y=44.8, ot="i", ahead={{q=8341, n="Lords of the Council", pn="Lordes do Conselho", i="Abyssal Signet", ip="Sinete Abissal", c=5}}, obj="Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.", pobj="Leve o Sinete Abissal para Bor Juba Agreste no Forte Cenariano."},
    {t="C", q=8323, n="True Believers", pn="Crentes Fiéis", lvl=59, req=54, xp=6400, cc=10, m=1451, x=37.81, y=44.38, ot="i", ahead={{q=8279, n="The Twilight Lexicon", pn="O dicionário do crepúsculo", i="Twilight Lexicon - Chapter 3", ip="Dicionário do Crepúsculo – Capítulo 3", c=1, qi=true},{q=8318, n="Secret Communication", pn="Comunicação secreta", i="Encrypted Twilight Text", ip="Texto Codificado do Crepúsculo", c=10, qi=true}}, obj="Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts", pobj="O Eremita Ortell quer que você lhe traga 10 Textos Codificados do Crepúsculo.", f={"coleta","drop"}},
    {t="C", q=8352, n="Scepter of the Council", pn="Cetro do conselho", lvl=60, req=60, xp=9950, cc=1, m=1451, x=39.6, y=45.08, ot="i", ahead={{q=9248, n="A Humble Offering", pn="Uma humilde oferenda", i="Abyssal Scepter", ip="Cetro Abissal", c=1}}, obj="Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.", pobj="Leve um Cetro Abissal para Bor Juba Agreste no Forte Cenariano."},
    {t="C", q=8309, n="Glyph Chasing", pn="À procura de glifos", lvl=60, req=58, xp=8300, m=1451, x=50.87, y=26.76, ot="i", objs={{n="Hive'Ashi Rubbing", p="Decalque de Colme'Ashi", m=1451, x=50.87, y=26.76},{n="Hive'Zora Rubbing", p="Decalque de Colme'Zora", m=1451, x=37.27, y=62.5},{n="Hive'Regal Rubbing", p="Decalque de Colme'Régia", m=1414, x=44.4, y=86.1}}, obj="Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.", pobj="Rutgar Formaglifo, no Acampamento Barbabronze, em Silithus, quer que você vá a Colme'Ashi, Colme'Zora e Colme'Régia e decalque os Cristais Entalhados de Glifos em cada colmeia.  Use o Kit de Transcrição do Geólogo para tirar um decalque razoável dos glifos antigos. Fale novamente com Rutgar Formaglifo quando terminar a tarefa."},
